<script setup lang="ts">
import { computed, ref } from 'vue'
import { app, gs, act, close, open, aimAt } from '../session'
import { onMounted } from 'vue'
import { loadMap } from '../core/store'
import { ABILITIES, ABILITY_NAME, CONDITIONS, EFFECTS, SKILLS, SKILL_IDS, SKILL_NAME, XP_LEVEL, signed } from '../rules/base'
import { availableSpells, castable, levelReady, sheet, type Hero } from '../rules/hero'
import { item } from '../rules/items'
import { spell, spellIcon, type Spell } from '../rules/spells'
import { background } from '../rules/races'
import { lookOf } from '../engine/compose'
import Stage3D from './Stage3D.vue'
const p = defineProps<{ own?: Hero | null; id?: string }>(); const emit = defineEmits<{ close: [] }>(); const tid = computed(() => p.id ?? app.seat); const h = computed(() => p.own ?? gs.value?.chars[tid.value] ?? null); const live = computed(() => !p.own && tid.value === app.seat); const S = computed(() => sheet(h.value!)); const tab = ref(app.modalArg === 'pack' ? 'pack' : app.modalArg === 'spells' ? 'spells' : 'main')
const scan = ref(''); onMounted(async () => { const k = h.value?.id; if (!k || (!p.own && !live.value)) return; try { const b = await loadMap('hero:' + k, 'scan'); if (b) scan.value = URL.createObjectURL(new Blob([b as any], { type: 'image/jpeg' })) } catch { /* none */ } })
const out = () => { emit('close'); if (!p.own) close() }; const TABS = computed(() => [['main', 'Sheet', ''], ['pack', 'Pack', ''], ...(S.value.cls.caster || h.value!.cantrips.length || h.value!.over?.spells?.length || S.value.race.cantrip ? [['spells', 'Spells', 'spell-book']] : []), ['feats', 'Features', 'muscle-up'], ['story', 'Story', ''], ...(scan.value ? [['scan', 'Your paper', '']] : [])]); const sel = ref(''); const it = computed(() => h.value!.inv.find(s => s.uid === sel.value)); const can = (i: any) => ['weapon', 'armor', 'shield', 'ring', 'wondrous', 'focus'].includes(i.kind)
const prep = ref<string[] | null>(null); const lists = computed(() => { const s = S.value; const pool = prep.value ? (h.value!.cls === 'wizard' ? h.value!.known.map(spell) : availableSpells(s)) : castable(s); const by: Record<number, Spell[]> = {}; for (const x of [...new Map(pool.map(q => [q.id, q])).values()]) (by[x.lv] ??= []).push(x); return Object.entries(by).map(([l, v]) => ({ l: +l, v: v.sort((a, b) => a.name.localeCompare(b.name)) })) }); const togPrep = (id: string) => { const i = prep.value!.indexOf(id); if (i >= 0) prep.value!.splice(i, 1); else if (prep.value!.length < S.value.prepMax) prep.value!.push(id) }; const donePrep = async () => { await act({ k: 'prepare', l: prep.value }); prep.value = null }
const slot = (l: number) => ({ max: S.value.slots[l - 1] ?? 0, used: h.value!.slots[l] ?? 0 }); const friends = computed(() => Object.entries(gs.value?.chars ?? {}).filter(([k]) => k !== tid.value)); const giveTo = ref(false); const notes = ref(''); const saveNotes = () => act({ k: 'notes', text: notes.value }); const use = (u: string, self = true) => { const x = h.value!.inv.find(s => s.uid === u)!; const i = item(x.id); if (i.use === 'throw' || (i.spell && i.kind !== 'potion')) { close(); const s = i.spell ? spell(i.spell) : null; aimAt({ k: 'item', id: u, name: i.name, icon: i.icon, who: app.seat, want: s?.fx.kind === 'heal' || s?.fx.kind === 'revive' ? 'friend' : s?.fx.kind === 'buff' ? 'friend' : 'foe', n: 1, ids: [], range: i.range?.[1] ?? s?.range ?? 60 }) } else void act({ k: 'item', u, t: self ? app.seat : undefined }) }
const cond = computed(() => (h.value?.conds ?? []).map(c => c.kind === 'fx' ? EFFECTS[c.id] : CONDITIONS[c.id]).filter(Boolean))
</script>
<template><div v-if="h" class="veil" @pointerdown.self="out"><section class="modal paper sheet" role="dialog" :aria-label="h.name"><aside><Stage3D :look="{ model: 'hero', hero: lookOf(h) }" /><div class="sd"><div v-if="S.nextXp" class="xpl"><span>{{ h.xp.toLocaleString() }} of {{ S.nextXp.toLocaleString() }} XP</span><div class="xp"><i :style="{ width: Math.max(0, Math.min(100, (h.xp - XP_LEVEL[h.level]) / (S.nextXp - XP_LEVEL[h.level]) * 100)) + '%' }" /></div></div><button v-if="live && levelReady(h)" class="btn primary wide" @click="open('level')">Level up</button><button v-if="live && h.insp" class="btn wide" :class="{ on: gs?.arm[app.seat]?.insp }" @click="act({ k: 'insp' })">{{ gs?.arm[app.seat]?.insp ? 'Inspiration readied' : 'Use inspiration' }}</button><button v-if="(live && gs?.set.ownSheets && !gs.combat) || (id && app.role === 'dm' && !own)" class="btn wide" @click="open('amend', live ? null : tid)">Amend the sheet</button></div></aside>
  <div class="main"><header><h2 class="cut">{{ h.name }}</h2><p class="cut">{{ h.over?.race ?? S.race.name }} {{ h.over?.cls ?? S.cls.name.toLowerCase() + ' ' + h.level }}{{ h.over ? ', own sheet' : '' }}</p><button class="x" aria-label="Close" @click="out">×</button></header><nav class="tabs"><button v-for="t in TABS" :key="t[0]" class="tab" :class="{ on: tab === t[0] }" @click="tab = t[0]">{{ t[1] }}</button></nav><div class="pg scroll">
    <template v-if="tab === 'main'"><div class="boxes"><div class="hpb"><b><template v-if="live && h.over"><input type="number" :value="h.hp" aria-label="Hit points" min="0" :max="S.max" @change="act({ k: 'hp', n: +($event.target as HTMLInputElement).value } as any)"></template><template v-else>{{ h.hp }}</template><i>/{{ S.max }}</i></b><span>Hit points{{ h.temp ? `, +${h.temp}` : '' }}</span></div><div v-tip="S.acNote"><b>{{ S.ac }}</b><span>Armour class</span></div><div><b>{{ signed(S.init) }}</b><span>Initiative</span></div><div><b>{{ S.speed }}</b><span>Speed</span></div><div><b>{{ signed(S.prof) }}</b><span>Proficiency</span></div><div><b>{{ S.pp }}</b><span>Passive sight</span></div><div><b>{{ h.hd }}<i>d{{ S.cls.hit }}</i></b><span>Hit dice</span></div></div><p v-if="cond.length" class="cond"><span v-for="c in cond" :key="c.name" v-tip="c.text">{{ c.name }}</span></p>
      <div class="cols"><div><table class="abil"><thead><tr><th /><th>Check</th><th>Score</th><th>Save</th></tr></thead><tbody><tr v-for="a in ABILITIES" :key="a"><th>{{ ABILITY_NAME[a] }}</th><td><button :disabled="!live" :aria-label="ABILITY_NAME[a] + ' check'" @click="act({ k: 'check', ab: a } as any)">{{ signed(S.mods[a]) }}</button></td><td>{{ S.score[a] }}</td><td><button :disabled="!live" :class="{ p: S.saveProf.includes(a) }" :aria-label="ABILITY_NAME[a] + ' save'" @click="act({ k: 'check', ab: a, save: 1 } as any)">{{ signed(S.saves[a]) }}</button></td></tr></tbody></table><h3>Attacks</h3><table class="t"><tbody><tr v-for="a in S.attacks" :key="a.id"><td><b>{{ a.name }}</b></td><td class="r">{{ signed(a.hit) }}</td><td>{{ a.dmg }} {{ a.type }}</td><td class="r">{{ a.ranged ? a.range.join('/') : a.reach }} ft</td></tr></tbody></table><p v-if="S.nAttacks > 1" class="muted">{{ S.nAttacks }} attacks each time you attack.</p></div><div class="sks"><button v-for="s in SKILL_IDS" :key="s" class="sk" :disabled="!live" @click="act({ k: 'check', skill: s })"><i :class="{ p: S.skills[s].p >= 1, e: S.skills[s].p === 2, h: S.skills[s].p === .5 }" /><span class="grow">{{ SKILL_NAME[s] }}</span><small>{{ SKILLS[s] }}</small><b>{{ signed(S.skills[s].v) }}</b></button></div></div></template>
    <template v-if="tab === 'pack'"><p><b class="gold">{{ h.gold }}</b> gold, {{ S.load }} of {{ S.carry }} lb</p><div class="cols"><div class="inv"><button v-for="s in h.inv" :key="s.uid" :class="{ on: sel === s.uid }" @click="sel = s.uid; giveTo = false"><span class="grow cut">{{ item(s.id).name }}<template v-if="s.n > 1"> × {{ s.n }}</template></span><small v-if="s.eq">worn</small></button><p v-if="h.over?.gear" class="gear">{{ h.over.gear }}</p></div><div v-if="it" class="det"><h3>{{ item(it.id).name }}</h3><p class="muted">{{ item(it.id).rarity ?? '' }} {{ item(it.id).kind }}<template v-if="item(it.id).cost">, worth {{ item(it.id).cost }}</template></p><p v-if="item(it.id).dmg">{{ item(it.id).dmg }} {{ item(it.id).type }}<template v-if="item(it.id).props?.length">, {{ item(it.id).props!.join(', ') }}</template></p><p v-if="item(it.id).ac">Armour class {{ item(it.id).ac }}<template v-if="item(it.id).noStealth">, noisy</template></p><p v-if="item(it.id).text">{{ item(it.id).text }}.</p><div v-if="live" class="chips"><button v-if="can(item(it.id))" class="btn sm" @click="act({ k: 'equip', u: it!.uid })">{{ it.eq ? 'Take off' : 'Equip' }}</button><button v-if="item(it.id).heal || item(it.id).use || item(it.id).spell || it.id === 'goodberry'" class="btn sm primary" @click="use(it!.uid)">Use</button><button v-if="friends.length" class="btn sm" @click="giveTo = !giveTo">Give</button><button class="btn sm" @click="act({ k: 'drop', u: it!.uid }); sel = ''">Drop</button></div><div v-if="giveTo" class="chips" style="margin-top:6px"><button v-for="[k, f] in friends" :key="k" class="chip s" @click="act({ k: 'give', u: it!.uid, t: k }); sel = ''">{{ f.name }}</button></div></div></div></template>
    <template v-if="tab === 'spells'"><div class="row wrap"><span class="grow">Save DC <b class="gold">{{ S.dc }}</b> Attack <b class="gold">{{ signed(S.spellHit) }}</b><template v-if="S.pact[0]"> Pact slots <b class="gold">{{ S.pact[0] - h.pact }}</b> of {{ S.pact[0] }}, level {{ S.pact[1] }}</template></span><template v-if="S.prepMax && live && !h.over"><button v-if="!prep" class="btn sm" :disabled="!!gs?.combat" @click="prep = [...h.prepared]">Prepare, {{ h.prepared.length }} of {{ S.prepMax }}</button><template v-else><span>{{ prep.length }} of {{ S.prepMax }}</span><button class="btn sm primary" @click="donePrep">Done</button></template></template></div><template v-for="g in lists" :key="g.l"><div class="sh"><h3>{{ g.l ? 'Level ' + g.l : 'Cantrips' }}</h3><span v-if="g.l && slot(g.l).max" class="pips"><i v-for="n in slot(g.l).max" :key="n" :class="{ off: n <= slot(g.l).used }" /></span></div><div class="sps"><button v-for="s in g.v" :key="s.id" :class="{ on: prep?.includes(s.id) }" :disabled="!prep || s.lv === 0" @click="prep && togPrep(s.id)"><b>{{ s.name }}</b><i>{{ s.time === 'action' ? '' : s.time + ', ' }}{{ s.range ? s.range + ' ft' : 'self' }}{{ s.conc ? ', concentration' : '' }}</i><small>{{ s.text }}</small></button></div></template></template>
    <template v-if="tab === 'feats'"><div class="fts"><div v-for="f in S.features" :key="f.src + f.id" class="ft"><b>{{ f.name }}</b> <small>{{ f.src }}{{ f.lv > 1 ? ' ' + f.lv : '' }}</small><span v-if="S.resMax[f.res ?? '']" class="tally"><template v-if="S.resMax[f.res!] <= 12"><i v-for="n in S.resMax[f.res!]" :key="n" :class="{ off: n <= (h.res[f.res!] ?? 0) }" /></template><template v-else>{{ S.resMax[f.res!] - (h.res[f.res!] ?? 0) }} of {{ S.resMax[f.res!] }}</template><template v-if="live && f.id.startsWith('own')"><button class="btn sm" :disabled="(h.res[f.res!] ?? 0) >= S.resMax[f.res!]" @click="act({ k: 'tally', k2: f.id, d: 1 } as any)">Use</button><button v-if="h.res[f.res!]" class="btn sm quiet" @click="act({ k: 'tally', k2: f.id, d: -1 } as any)">Back</button></template></span><p>{{ f.text }}</p></div></div></template>
    <template v-if="tab === 'story'"><h3>{{ h.over?.bg ?? background(h.bg).name }}</h3><p>{{ background(h.bg).feature }}</p><p v-if="h.story" class="aloud">{{ h.story }}</p><p class="muted">{{ h.kills }} slain, {{ h.campaigns }} campaign{{ h.campaigns === 1 ? '' : 's' }}. Speaks {{ h.over?.langs ?? S.race.langs.join(', ') }}.</p><template v-if="live"><h3>Notes</h3><textarea class="field" rows="9" :value="h.notes" aria-label="Notes" @input="notes = ($event.target as HTMLTextAreaElement).value" @change="saveNotes" /></template><p v-else style="white-space:pre-wrap">{{ h.notes }}</p></template>
    <img v-if="tab === 'scan'" :src="scan" class="scan" alt="Your own sheet">
  </div></div></section></div></template>
<style scoped>
.sheet{width:min(1060px,100%);height:min(760px,100%);flex-direction:row}.sheet aside{width:270px;background:var(--spot);position:relative;flex:none;display:flex;flex-direction:column}.sheet aside>:deep(canvas){flex:1;min-height:0}.sd{background:var(--paper);padding:10px 14px 14px;display:grid;gap:6px;border-right:2px solid var(--ink);border-top:2px solid var(--ink)}.xpl{font-size:15px}.main{flex:1;min-width:0;display:flex;flex-direction:column}.main header{display:flex;align-items:baseline;gap:16px;padding:14px 12px 6px 22px}.main h2{font:800 38px/1 var(--serif)}.main header p{flex:1;margin:0;font-size:17px;color:var(--ink2)}.x{font:400 36px/.8 var(--ui);width:44px;height:40px;text-align:center}.x:hover{background:var(--spot);color:var(--on-spot)}.tabs{padding:0 12px}.pg{flex:1;min-height:0;padding:18px 22px 24px}
.boxes{display:grid;grid-template-columns:1.5fr repeat(6,1fr);border:2px solid var(--ink);margin-bottom:14px}.boxes div{border-right:2px solid var(--ink);text-align:center;padding:9px 2px 7px}.boxes div:last-child{border:0}.boxes b{font:800 37px/.86 var(--serif);display:block}.boxes i{font-style:normal;font-size:22px}.boxes span{font-size:14px;color:var(--ink2);display:block;margin-top:5px}.boxes input{font:inherit;width:62px;border:0;background:#fff;text-align:center;color:inherit;padding:0;-moz-appearance:textfield}.boxes input::-webkit-inner-spin-button{display:none}.cond{display:flex;gap:5px;flex-wrap:wrap}.cond span{background:var(--ink);color:var(--paper);padding:1px 9px}
.cols{display:grid;grid-template-columns:1.2fr 1fr;gap:30px}.abil{width:100%;border-collapse:collapse}.abil th{text-align:left;font:600 17px var(--ui)}.abil thead th{font-weight:400;font-size:14px;color:var(--ink2);text-align:center}.abil td{text-align:center;border-bottom:1px solid var(--line);padding:0;font-size:17px}.abil tbody th{border-bottom:1px solid var(--line)}.abil button{font:800 25px/34px var(--serif);width:100%;text-align:center;color:inherit}.abil button:hover:not(:disabled){background:var(--spot);color:var(--on-spot)}.abil td:last-child button{font-size:21px;font-weight:600;color:var(--ink2)}.abil .p{color:var(--ink)!important;font-weight:800!important}h3{margin:20px 0 6px}
.sk{display:flex;align-items:center;gap:9px;width:100%;font-size:16.5px;line-height:29px;border-bottom:1px solid var(--line)}.sk:hover:not(:disabled){background:var(--spot);color:var(--on-spot)}.sk i{width:13px;height:13px;border:2px solid currentColor}.sk i.p{background:currentColor}.sk i.e{background:var(--spot);box-shadow:inset 0 0 0 2px var(--ink)}.sk i.h{background:linear-gradient(90deg,currentColor 50%,transparent 50%)}.sk small{color:inherit;opacity:.6}.sk b{width:34px;text-align:right;font:700 20px/1 var(--serif)}
.gold{font:800 24px/1 var(--serif)}.inv{align-content:start;display:grid}.inv button{display:flex;gap:9px;padding:5px 8px;border-bottom:1px solid var(--line)}.inv button:hover{background:var(--paper2)}.inv .on{background:var(--ink)!important;color:var(--paper)}.inv small{font-size:14.5px;opacity:.75}.gear{white-space:pre-wrap;margin-top:10px;color:var(--ink2)}.det{position:sticky;top:0;align-self:start;border-top:6px solid var(--spot);padding:10px 0 0}.det h3{margin-top:0}.det p{margin:0 0 6px}
.sh{display:flex;align-items:center;gap:14px;border-bottom:3px solid var(--ink);margin-top:18px;padding-bottom:4px}.sh h3{margin:0}.sps{display:grid;grid-template-columns:1fr 1fr;gap:0 26px}.sps button{display:block;padding:7px 0;border-bottom:1px solid var(--line);color:inherit}.sps .on{background:var(--ink);color:var(--paper);padding-left:9px}.sps .on small,.sps .on i{color:inherit}.sps b{font:700 19px/1.05 var(--serif)}.sps i{font-style:normal;font-size:14.5px;color:var(--ink2);margin-left:8px}.sps small{display:block;font-size:15px;line-height:1.25;color:var(--ink2)}.pips,.tally{display:inline-flex;gap:5px;align-items:center;margin-left:10px}.pips i,.tally i{width:16px;height:16px;border:2px solid var(--ink);background:var(--spot)}.pips .off,.tally .off{background:none}.fts{columns:2;column-gap:34px}.ft{break-inside:avoid;margin-bottom:12px}.ft b{font:700 19px/1.1 var(--serif)}.ft small{font-size:14.5px;color:var(--ink2)}.ft p{margin:2px 0 0;font-size:16px;line-height:1.32}.scan{width:100%}
@media(max-width:760px){.sheet{flex-direction:column;height:100%}.sheet aside{width:100%;height:auto;flex-direction:row}.sheet aside>:deep(canvas){height:120px;flex:0 0 120px}.sd{flex:1;border:0}.cols,.sps{grid-template-columns:1fr;gap:14px}.fts{columns:1}.boxes{grid-template-columns:repeat(4,1fr)}.boxes div{border-bottom:2px solid var(--ink)}.hpb{grid-column:span 2}.tabs{overflow-x:auto}.main h2{font-size:29px}.pg{padding:14px 16px}}
</style>
